"use client";

import {
  type ButtonHTMLAttributes,
  createContext,
  type DialogHTMLAttributes,
  type HTMLAttributes,
  type MouseEvent,
  type ReactNode,
  use,
  useCallback,
  useEffect,
  useId,
  useRef,
  useState,
} from "react";
import { createSwipe } from "../interaction/swipe";
import { cx } from "../utils/cx";
import { Slot } from "../utils/slot";

type DialogContextValue = {
  open: boolean;
  setOpen: (open: boolean) => void;
  titleId: string;
  descriptionId: string;
};
const DialogContext = createContext<DialogContextValue | null>(null);

function useDialog(part: string): DialogContextValue {
  const ctx = use(DialogContext);
  if (!ctx) throw new Error(`<${part}> must be inside <Dialog>`);
  return ctx;
}

export type DialogProps = {
  open?: boolean;
  defaultOpen?: boolean;
  onOpenChange?: (open: boolean) => void;
  children: ReactNode;
};

/**
 * A modal dialog on the native <dialog> element: the browser provides the top layer, focus trapping, Escape and
 * focus return. Holominimal adds the elevated surface, the scrim, an entrance and exit, and backdrop-click to close.
 */
export function Dialog({ open: controlled, defaultOpen = false, onOpenChange, children }: DialogProps) {
  const [uncontrolled, setUncontrolled] = useState(defaultOpen);
  const open = controlled ?? uncontrolled;
  const setOpen = useCallback(
    (next: boolean) => {
      if (controlled === undefined) setUncontrolled(next);
      onOpenChange?.(next);
    },
    [controlled, onOpenChange],
  );
  const id = useId();
  return (
    <DialogContext value={{ open, setOpen, titleId: `${id}-title`, descriptionId: `${id}-description` }}>
      {children}
    </DialogContext>
  );
}

export function DialogTrigger({
  asChild,
  onClick,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }) {
  const { open, setOpen } = useDialog("DialogTrigger");
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      {...(asChild ? {} : { type: "button" as const })}
      {...(rest as object)}
      aria-haspopup="dialog"
      aria-expanded={open}
      onClick={(e: MouseEvent<HTMLButtonElement>) => {
        onClick?.(e);
        if (!e.defaultPrevented) setOpen(true);
      }}
    />
  );
}

export type DialogContentProps = Omit<DialogHTMLAttributes<HTMLDialogElement>, "open"> & {
  /**
   * `center` (default), `top` (a command palette sits high), or a side sheet: `left`, `right` or `bottom`. Side sheets
   * slide in from their edge and, on touch, swipe back toward it to close.
   */
  position?: "center" | "top" | "left" | "right" | "bottom";
  size?: "sm" | "md" | "lg";
  /** Close when the scrim is clicked. Default true. */
  dismissible?: boolean;
};

export function DialogContent({
  position = "center",
  size = "md",
  dismissible = true,
  className,
  children,
  onClick,
  ...rest
}: DialogContentProps) {
  const { open, setOpen, titleId, descriptionId } = useDialog("DialogContent");
  const ref = useRef<HTMLDialogElement>(null);
  useEffect(() => {
    const el = ref.current;
    if (!el) return;
    if (open && !el.open) el.showModal();
    else if (!open && el.open) el.close();
  }, [open]);
  useEffect(() => {
    const el = ref.current;
    if (!el || !open || !(position === "left" || position === "right" || position === "bottom")) return;
    const away = position === "left" ? "left" : position === "right" ? "right" : "down";
    return createSwipe(el, { onSwipe: (d) => d === away && setOpen(false) });
  }, [open, position, setOpen]);
  return (
    <dialog
      {...rest}
      ref={ref}
      className={cx("hm-dialog", className)}
      data-position={position}
      data-size={size}
      aria-labelledby={titleId}
      aria-describedby={descriptionId}
      onClose={() => setOpen(false)}
      onCancel={(e) => {
        if (!dismissible) e.preventDefault();
      }}
      onClick={(e) => {
        onClick?.(e);
        // a click whose target is the <dialog> itself landed on the ::backdrop (the content box fills the element)
        if (dismissible && e.target === e.currentTarget) setOpen(false);
      }}
    >
      <div className="hm-dialog-box">{children}</div>
    </dialog>
  );
}

export function DialogTitle({ className, ...rest }: HTMLAttributes<HTMLHeadingElement>) {
  const { titleId } = useDialog("DialogTitle");
  return <h2 {...rest} id={titleId} className={cx("hm-dialog-title", className)} />;
}

export function DialogDescription({ className, ...rest }: HTMLAttributes<HTMLParagraphElement>) {
  const { descriptionId } = useDialog("DialogDescription");
  return <p {...rest} id={descriptionId} className={cx("hm-dialog-description", className)} />;
}

export function DialogFooter({ className, ...rest }: HTMLAttributes<HTMLDivElement>) {
  return <div {...rest} className={cx("hm-dialog-footer", className)} />;
}

export function DialogClose({
  asChild,
  onClick,
  ...rest
}: ButtonHTMLAttributes<HTMLButtonElement> & { asChild?: boolean }) {
  const { setOpen } = useDialog("DialogClose");
  const Comp = asChild ? Slot : "button";
  return (
    <Comp
      {...(asChild ? {} : { type: "button" as const })}
      {...(rest as object)}
      onClick={(e: MouseEvent<HTMLButtonElement>) => {
        onClick?.(e);
        if (!e.defaultPrevented) setOpen(false);
      }}
    />
  );
}
